import{_ as r,c as t,o as a,ag as o}from"./chunks/framework.BgId8OS5.js";const p=JSON.parse('{"title":"UE1208 - Web 1","description":"","frontmatter":{},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),i={name:"index.md"};function n(s,e,l,u,c,d){return a(),t("div",null,e[0]||(e[0]=[o('<h1 id="ue1208-web-1" tabindex="-1">UE1208 - Web 1 <a class="header-anchor" href="#ue1208-web-1" aria-label="Permalink to &quot;UE1208 - Web 1&quot;">​</a></h1><p>Bienvenue dans ce guide complet pour apprendre la programmation web (côté client) ! Ce cours vous accompagnera progressivement depuis les bases du HTML jusqu&#39;aux concepts avancés de JavaScript.</p><h2 id="🌟-commencer-par-les-fondamentaux" tabindex="-1">🌟 Commencer par les fondamentaux <a class="header-anchor" href="#🌟-commencer-par-les-fondamentaux" aria-label="Permalink to &quot;🌟 Commencer par les fondamentaux&quot;">​</a></h2><p><strong>Nouveau dans la programmation web ?</strong> Commencez par lire notre <a href="/introduction-generale.html">Introduction générale à la programmation web</a> qui vous expliquera les concepts fondamentaux, la philosophie du développement web moderne et l&#39;écosystème dans lequel vous allez évoluer.</p><p>Cette introduction vous aidera à comprendre :</p><ul><li>Pourquoi HTML, CSS et JavaScript forment un trio indissociable</li><li>Comment ces technologies s&#39;articulent pour créer des expériences web</li><li>Les principes de l&#39;accessibilité et du design inclusif</li><li>L&#39;importance de la performance et de l&#39;expérience utilisateur</li><li>Le mindset du développeur web moderne</li></ul><h2 id="🎯-objectifs-du-cours" tabindex="-1">🎯 Objectifs du cours <a class="header-anchor" href="#🎯-objectifs-du-cours" aria-label="Permalink to &quot;🎯 Objectifs du cours&quot;">​</a></h2><ul><li>Maîtriser les fondamentaux du HTML pour structurer des pages web</li><li>Apprendre CSS pour styliser et animer vos interfaces</li><li>Développer des compétences en JavaScript pour créer des sites interactifs</li><li>Découvrir les bonnes pratiques du développement web moderne</li></ul><h2 id="📚-structure-du-cours" tabindex="-1">📚 Structure du cours <a class="header-anchor" href="#📚-structure-du-cours" aria-label="Permalink to &quot;📚 Structure du cours&quot;">​</a></h2><p>Ce cours est organisé en 13 chapitres suivant une progression logique :</p><h3 id="🏗️-fondations" tabindex="-1">🏗️ Fondations <a class="header-anchor" href="#🏗️-fondations" aria-label="Permalink to &quot;🏗️ Fondations&quot;">​</a></h3><ol><li><strong>Fondamentaux HTML</strong> - Structure et sémantique</li><li><strong>Formulaires HTML</strong> - Interaction utilisateur</li><li><strong>Fondamentaux CSS</strong> - Styles et mise en page</li></ol><h3 id="🎨-interface-et-design" tabindex="-1">🎨 Interface et Design <a class="header-anchor" href="#🎨-interface-et-design" aria-label="Permalink to &quot;🎨 Interface et Design&quot;">​</a></h3><ol start="4"><li><strong>Navigation et Menu</strong> - Navigation utilisateur</li><li><strong>Animations et Transitions CSS</strong> - Effets visuels</li></ol><h3 id="⚡-programmation" tabindex="-1">⚡ Programmation <a class="header-anchor" href="#⚡-programmation" aria-label="Permalink to &quot;⚡ Programmation&quot;">​</a></h3><ol start="6"><li><strong>Fondamentaux JavaScript</strong> - Syntaxe et logique</li><li><strong>JavaScript et DOM</strong> - Manipulation des éléments</li><li><strong>Gestion des Événements</strong> - Interactivité</li></ol><h3 id="🚀-concepts-avances" tabindex="-1">🚀 Concepts Avancés <a class="header-anchor" href="#🚀-concepts-avances" aria-label="Permalink to &quot;🚀 Concepts Avancés&quot;">​</a></h3><ol start="9"><li><strong>Programmation Interactive</strong> - Jeux et interactions</li><li><strong>Interface Utilisateur Avancée</strong> - Composants dynamiques</li><li><strong>Programmation Asynchrone</strong> - API et requêtes</li><li><strong>Stockage Local</strong> - Persistance des données</li><li><strong>Qualité et Bonnes Pratiques</strong> - Code professionnel</li></ol><h2 id="🚀-comment-utiliser-ce-cours" tabindex="-1">🚀 Comment utiliser ce cours <a class="header-anchor" href="#🚀-comment-utiliser-ce-cours" aria-label="Permalink to &quot;🚀 Comment utiliser ce cours&quot;">​</a></h2><ol><li><strong>Suivez l&#39;ordre</strong> : Les chapitres sont conçus pour s&#39;appuyer les uns sur les autres</li><li><strong>Pratiquez</strong> : Chaque concept est accompagné d&#39;exemples pratiques</li><li><strong>Expérimentez</strong> : N&#39;hésitez pas à modifier les exemples pour mieux comprendre</li><li><strong>Progressez à votre rythme</strong> : Prenez le temps de bien assimiler chaque notion</li></ol><h2 id="🛠️-prerequis" tabindex="-1">🛠️ Prérequis <a class="header-anchor" href="#🛠️-prerequis" aria-label="Permalink to &quot;🛠️ Prérequis&quot;">​</a></h2><ul><li>Aucune expérience préalable en programmation requise</li><li>Un navigateur web moderne (Chrome, Firefox, Safari, Edge)</li><li>Un éditeur de code (VS Code recommandé)</li><li>Motivation et curiosité ! 🎉</li></ul><hr><p><strong>Prêt à commencer ?</strong> Dirigez-vous vers le premier chapitre : <a href="/html/structure-base.html">Fondamentaux HTML</a></p>',24)]))}const g=r(i,[["render",n]]);export{p as __pageData,g as default};
